/**
 * REGISTRE_RGPD.json is generated by scripts/gdpr-suite.mjs. Contract: the committed file is exactly what the generator produces, every duration in it comes from
 * the code (RETENTION in cron/gdpr-purge, RETENTION_POLICY_REGISTRY in privacy.js), and it makes no unsupported claim (DPO, signed DPA, Zero-Knowledge, Gemini as recipient).
 * Reference: LEGAL_FR/06_REGISTRE_TRAITEMENTS.md §3.
 */
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { RETENTION } from '../../api/_handlers/cron/gdpr-purge.js';
import { RETENTION_POLICY_REGISTRY } from '../../api/_services/privacy.js';
import { buildRegistre, generateRegistreContent, readCodeSources, REGISTRE_DATE_REVISION, CONTACT_PROTECTION_DONNEES } from '../../scripts/gdpr-suite.mjs';

const ROOT = path.resolve(__dirname, '../..');
const fileText = fs.readFileSync(path.join(ROOT, 'REGISTRE_RGPD.json'), 'utf-8');
const registre = JSON.parse(fileText);
const conservations = registre.traitements.flatMap((t) => t.conservation.map((c) => ({ id: t.id, ...c })));

describe('REGISTRE_RGPD.json — generated, consistent with the code', () => {
  it('equals what scripts/gdpr-suite.mjs generates (regenerate with `node scripts/gdpr-suite.mjs`)', () => {
    expect(fileText).toBe(generateRegistreContent(ROOT));
  });

  it('static parsing of the sources matches the runtime constants', () => {
    const { retention, registry } = readCodeSources(ROOT);
    expect(retention).toEqual(RETENTION);
    for (const [key, r] of Object.entries(RETENTION_POLICY_REGISTRY)) {
      expect(registry[key], key).toEqual({ durationDays: r.durationDays, action: r.action, implementedBy: r.implementedBy ?? null });
    }
  });

  it('every RETENTION-sourced duration equals the purge constant', () => {
    const fromCron = conservations.filter((c) => c.source?.startsWith('RETENTION.'));
    expect(fromCron.length).toBeGreaterThan(0);
    for (const c of fromCron) {
      const key = c.source.slice('RETENTION.'.length);
      expect(c.duree_jours, `${c.id} ${c.source}`).toBe(RETENTION[key]);
      expect(c.description).toContain(String(RETENTION[key]));
    }
    // every purge constant is used at least once
    const used = new Set(fromCron.map((c) => c.source.slice('RETENTION.'.length)));
    for (const key of Object.keys(RETENTION)) expect(used.has(key), key).toBe(true);
    expect(conservations.find((c) => c.source === 'RETENTION.CONVERSATION_LOG_DAYS' && c.id === 'T08').duree_jours).toBe(90);
  });

  it('every registry-sourced duration equals RETENTION_POLICY_REGISTRY, and unimplemented rules say "non appliqué"', () => {
    const fromRegistry = conservations.filter((c) => c.source?.startsWith('RETENTION_POLICY_REGISTRY.'));
    expect(fromRegistry.length).toBeGreaterThan(0);
    for (const c of fromRegistry) {
      const r = RETENTION_POLICY_REGISTRY[c.source.slice('RETENTION_POLICY_REGISTRY.'.length)];
      expect(c.duree_jours, c.source).toBe(r.durationDays);
      expect(c.statut, c.source).toBe(r.implementedBy === null ? 'non appliqué' : 'appliqué');
    }
    const inactive = fromRegistry.find((c) => c.source === 'RETENTION_POLICY_REGISTRY.INACTIVE_ACCOUNT');
    expect(RETENTION_POLICY_REGISTRY.INACTIVE_ACCOUNT.implementedBy).toBeNull();
    expect(inactive.statut).toBe('non appliqué');
    expect(inactive.description).toMatch(/^non appliqué/);
    const shared = conservations.filter((c) => c.source_registre === 'RETENTION_POLICY_REGISTRY.SHARED_DIAGNOSTIC');
    expect(shared.length).toBeGreaterThan(0);
    for (const c of shared) expect(c.duree_jours_registre).toBe(RETENTION_POLICY_REGISTRY.SHARED_DIAGNOSTIC.durationDays);
  });

  it('no G14 entry still says its branch is not merged (all G14 branches are in release a628f7b)', () => {
    expect(fileText).not.toMatch(/non fusionn/i);
    expect(fileText).not.toMatch(/not merged/i);
    const src = fs.readFileSync(path.join(ROOT, 'scripts/gdpr-suite.mjs'), 'utf-8');
    expect(src).not.toMatch(/non fusionn|not merged here/i);
    for (const id of ['T08', 'T23', 'T24', 'T25', 'T26']) {
      const t = registre.traitements.find((x) => x.id === id);
      expect(JSON.stringify(t), id).toMatch(/fusionnée dans la version a628f7b/);
    }
  });

  it('makes no unsupported claim', () => {
    expect(fileText).not.toMatch(/zero[- ]?knowledge/i);
    expect(fileText).not.toMatch(/"dpa":\s*"Oui"/i);
    expect(fileText).not.toMatch(/dpo@/i);
    expect(fileText).not.toMatch(/bcrypt/i);
    expect(fileText).not.toMatch(/"dpo_contact"/);
    expect(registre.dpo).toBeNull();
    expect(registre.contact_protection_donnees).toBe(CONTACT_PROTECTION_DONNEES);
    expect(registre.organisme.statut).toBe('NOT_CREATED');   // R42-A01: no association created
    expect(registre.organisme.exploitant).toBe('NATURAL_PERSON');
    expect(registre.organisme.responsable_traitement).toMatch(/Personne physique porteuse du projet/);
    expect(registre.organisme.responsable_traitement).toMatch(/n'est pas présentée comme responsable/);
    // legal v5: an agreement incorporated by a provider's terms is recorded as such — never as a signed one
    for (const s of registre.sous_traitants) expect(s.dpa, s.nom).toMatch(/^(inconnu \/ non signé|intégré aux conditions de service \(non signé\) — pages publiques lues le (15|09)\/11\/2026|intégré aux conditions de service \(non signé\) — DPA Cloudflare v6\.4 \(3 avril 2026\) lu le 23\/11\/2026, accepté en ligne \(décision du fondateur du 23\/11\/2026\)|intégré aux conditions de service \(non signé\) — DPA Cloudflare lu le 09\/11\/2026 ; version 6\.4 \(3 avril 2026\) accepté en ligne \(décision du fondateur du 23\/11\/2026\)|accepté dans la console par le responsable de traitement \(déclaration du 13\/11\/2026\) — PDF non archivé, non signé séparément|8x8 Global DPA \(version 2025-02\) approuvé en principe par le fondateur \(décision du 23\/11\/2026\) — acceptation contractuelle non confirmée par le fournisseur, non signé|DPA Microsoft \(Products and Services Data Protection Addendum\) — NON VÉRIFIÉ \(aucune preuve archivée\), non signé)$/);
    for (const s of registre.sous_traitants) expect(s.dpa, s.nom).not.toMatch(/(?<!non )signé(?! séparément)/);
    expect(registre.transferts_hors_ue).toMatch(/aucun signé/);
  });

  it('24/11 fact-check: 8x8 (JaaS) listed as approved in principe (unsigned DPA) with SCC module 2; Outlook / Graph live since release 2, DPA not verified; Mailjet live since 18/11', () => {
    const find = (/** @type {RegExp} */ rx) => registre.sous_traitants.find((/** @type {any} */ s) => rx.test(s.nom));
    const jaas = find(/^8x8/);
    expect(jaas.dpa).toMatch(/2025-02\) approuvé en principe par le fondateur/); expect(jaas.statut_contrat).toBe('approuvé en principe par le fondateur'); expect(jaas.mecanisme_transfert).toMatch(/2021\/914, module 2/); expect(jaas.statut).toMatch(/AIPD A1/);
    const graph = find(/Outlook \/ Graph/);
    expect(graph.statut).toMatch(/release 2 \(OUTLOOK_ENABLED=true\)/); expect(graph.dpa).toMatch(/NON VÉRIFIÉ/);
    // founder 24/11: « accepté » only where an acceptance is recorded; « examiné » = read; the founder's decision alone = « approuvé en principe »
    for (const s of registre.sous_traitants) expect(['accepté', 'accepté en ligne (décision du fondateur du 23/11/2026)', 'examiné', 'approuvé en principe par le fondateur', 'non vérifié', 'sans objet'], s.nom).toContain(s.statut_contrat);
    for (const s of registre.sous_traitants) if (s.statut_contrat.startsWith('accepté')) expect(s.dpa, s.nom).toMatch(/^accepté|accepté en ligne/);
    expect(graph.statut_contrat).toBe('non vérifié');
    // owner 23/11: « Cloudflare DPA (v6.4) çevrim içi kabul edilmiş sayılır » — both Cloudflare entries carry the same status and DPA version
    const cloudflare = registre.sous_traitants.filter((/** @type {any} */ s) => /^Cloudflare/.test(s.nom));
    expect(cloudflare.map((/** @type {any} */ s) => s.nom)).toEqual(['Cloudflare (R2)', 'Cloudflare, Inc. (Workers AI)']);
    for (const s of cloudflare) { expect(s.statut_contrat, s.nom).toBe('accepté en ligne (décision du fondateur du 23/11/2026)'); expect(s.dpa, s.nom).toMatch(/6\.4 \(3 avril 2026\).*accepté en ligne \(décision du fondateur du 23\/11\/2026\)/); expect(s.dpa, s.nom).not.toMatch(/examiné/); }
    expect(find(/^Mailjet/).statut).toMatch(/^en service depuis le 18\/11\/2026/); expect(find(/^Mailjet/).statut).not.toMatch(/non approuvée/);
  });

  it('Gemini is blocked, not a recipient; the assistant uses local Ollama', () => {
    expect(registre.sous_traitants.some((s) => /gemini/i.test(s.nom))).toBe(false);
    const gemini = registre.services_non_destinataires.find((s) => /gemini/i.test(s.nom));
    expect(gemini.statut).toBe('bloqué');
    for (const t of registre.traitements) for (const d of t.destinataires) expect(d).not.toMatch(/gemini/i);
    const assistant = registre.traitements.find((t) => t.id === 'T08');
    expect(assistant.modele_ia).toMatch(/Ollama/);
  });

  it('Vercel: fra1 (EU) region, US contracting entity, SCC module 2 read on 15/11/2026; Vercel and Sinch are also controllers for some technical data', () => {
    const vercel = registre.sous_traitants.find((s) => s.nom === 'Vercel');
    expect(vercel.localisation).toMatch(/fra1/);
    expect(vercel.entite_contractante).toMatch(/USA/);
    expect(vercel.mecanisme_transfert).toMatch(/2021\/914, module 2/);
    expect(vercel.role_propre).toMatch(/responsable de traitement pour les données d'usage/);
    const mailjet = registre.sous_traitants.find((s) => s.nom === 'Mailjet (Sinch)');
    expect(mailjet.role_propre).toMatch(/responsable de traitement indépendant/);
    expect(mailjet.mecanisme_transfert).toMatch(/pas de Data Privacy Framework pour Mailjet/);
    expect(mailjet.journaux).toMatch(/90 jours \(offre gratuite\) ou 13 mois \(offre payante\)/);
    // legal v6 (17/11/2026): Upstash's DPA excludes its own security / service-analytics processing
    expect(registre.sous_traitants.filter((s) => s.role_propre).map((s) => s.nom)).toEqual(['Vercel', 'Upstash', 'Mailjet (Sinch)']);
  });

  it('diagnostic, OpenFisca and erasure are described as implemented', () => {
    const diag = registre.traitements.find((t) => t.id === 'T02');
    expect(diag.lieux_traitement.join(' ')).toMatch(/non stockées par \/api\/diagnostic/);
    expect(diag.lieux_traitement.join(' ')).toMatch(/SharedDiagnostic\.situation/);
    expect(diag.services_refuses.join(' ')).toMatch(/OpenFisca.*refusé en production/);
    expect(registre.droits_exercables.join(' ')).toMatch(/revue humaine/);
    expect(registre.droits_exercables.join(' ')).toMatch(/\/api\/auth\/export-data/);
    expect(registre.droits_exercables.join(' ')).not.toMatch(/gdpr-suite/);
  });

  it('G14 owner legal approval (23/11/2026): P18, P19, P20 and the social referrals carry decided bases and durations; Cloudflare DPA v6.4 accepted online', () => {
    const t = (/** @type {string} */ id) => registre.traitements.find((x) => x.id === id);
    expect(registre.version).toBe('0.8');   // G14-R3 (24/11/2026): T29–T32; 0.8 = Release 3 owner approval (24/11/2026)
    expect(t('T02').base_legale_g14).toMatch(/P18 : intérêt légitime .*\(art\. 6\.1\.f\) — décidé par le responsable le 23\/11\/2026$/);
    expect(t('T02').base_legale_proposee).toMatch(/^Intérêt légitime .*P18, décidé par le responsable le 23\/11\/2026$/);
    expect(t('T08').base_legale_proposee).toMatch(/P19, décidé par le responsable le 23\/11\/2026$/);
    expect(t('T08').evolution_g14).toMatch(/base : intérêt légitime \(art\. 6\.1\.f\) — décidé par le responsable le 23\/11\/2026$/);
    expect(t('T25').base_legale_proposee).toMatch(/^Intérêt légitime \(art\. 6\.1\.f\) — notice v12 \/ v13, P20, décidé par le responsable le 23\/11\/2026$/);
    expect(t('T24').conservation[0].description).toBe('12 mois après la clôture (décision du responsable du 23/11/2026)');
    for (const id of ['T08', 'T24', 'T25']) expect(JSON.stringify(t(id)), id).not.toMatch(/à valider|proposé|à confirmer/i);
    expect(JSON.stringify(t('T02'))).not.toMatch(/proposé, à valider|à confirmer/);
    const cf = registre.sous_traitants.find((x) => x.nom === 'Cloudflare, Inc. (Workers AI)');
    expect(cf.mecanisme_transfert).not.toMatch(/sans signature|à confirmer/);
    expect(cf.dpa).toMatch(/DPA Cloudflare v6\.4 \(3 avril 2026\) lu le 23\/11\/2026, accepté en ligne \(décision du fondateur du 23\/11\/2026\)$/);
    expect(JSON.stringify(registre)).not.toMatch(/application du DPA sans signature/);
    expect(JSON.stringify(registre)).not.toMatch(/avocat|juriste a validé|expert a validé/);
  });

  it('date_mise_a_jour is the fixed revision date, not the run date', () => {
    expect(registre.date_mise_a_jour).toBe('2026-11-24');   // G14-R3: T29–T32 (2026-11-23 = G14 consolidation: T23–T26, Cloudflare Workers AI, Scaleway OpenFisca; FA-D5 (2026-11-18): backups, Scaleway, Cloudflare, erasure traces (2026-11-17 = legal v6, 2026-11-15 = v5, 2026-11-04 = R42-LEGAL)
    expect(REGISTRE_DATE_REVISION).toBe('2026-11-24');
    const built = buildRegistre(readCodeSources(ROOT));
    expect(built.date_mise_a_jour).toBe(REGISTRE_DATE_REVISION);
  });

  it('R42: appointments require an account, the account-free flow is retired, the decoy is a PostgreSQL row without personal data, analytics off by default', () => {
    const rdv = registre.traitements.find((t) => t.id === 'T06');
    expect(rdv.statut).toMatch(/un compte est exigé/);
    expect(rdv.statut).toMatch(/sans compte est retirée/);
    expect(rdv.base_legale_proposee).toMatch(/^À VALIDER PAR LE RESPONSABLE DE TRAITEMENT/);
    const decoy = rdv.conservation.find((c) => /Leurre/.test(c.donnee));
    expect(decoy.donnee).toMatch(/PostgreSQL/);
    expect(decoy.donnee).toMatch(/sans aucune donnée personnelle/);
    expect(decoy.donnee).toMatch(/plus aucun stockage KV/);
    expect(registre.traitements.find((t) => t.id === 'T17').statut).toMatch(/désactivé par défaut/);
    expect(fileText).not.toMatch(/Personnes ayant réservé sans compte \(R38, optionnel/);
  });

  it('FA-D5: backups (Scaleway runs, Cloudflare R2 stores), the erasure traces (Upstash + encrypted R2 copy) are in the register, durations read from the code', async () => {
    const { TOMBSTONE_TTL_SECONDS } = await import('../../api/_services/erasure-tombstones.js');
    const { COPY_RETENTION_DAYS } = await import('../../api/_services/erasure-tombstone-copy.js');
    const { RETENTION_POLICY } = await import('../../api/_services/retention-policy.js');
    const scw = registre.sous_traitants.find((s) => /^Scaleway/.test(s.nom));
    expect(scw.localisation).toMatch(/Paris/);
    expect(scw.role).toMatch(/sauvegarde/i);
    const cf = registre.sous_traitants.find((s) => /^Cloudflare/.test(s.nom));
    expect(cf.role).toMatch(/sauvegardes chiffrées/);
    expect(cf.role).toMatch(/seconde copie chiffrée des traces d'effacement/);
    expect(cf.localisation).toMatch(/juridiction UE/);
    expect(cf.mecanisme_transfert).toMatch(/2021\/914/);
    const t = registre.traitements.find((x) => x.id === 'T22');
    expect(t.nom).toMatch(/Sauvegardes/);
    expect(t.sous_traitants.join(' ')).toMatch(/Scaleway/);
    expect(t.sous_traitants.join(' ')).toMatch(/Cloudflare/);
    expect(t.sous_traitants.join(' ')).toMatch(/Upstash/);
    const d = Object.fromEntries(t.conservation.map((c) => [c.source, c.duree_jours]));
    expect(d['retention-policy.BACKUP_KEEP_DAYS']).toBe(RETENTION_POLICY.durations.BACKUP_KEEP_DAYS.days);
    expect(d['erasure-tombstones.TOMBSTONE_TTL_SECONDS']).toBe(TOMBSTONE_TTL_SECONDS / 86400);
    expect(d['erasure-tombstone-copy.COPY_RETENTION_DAYS']).toBe(COPY_RETENTION_DAYS);
    expect(t.categories_donnees.join(' ')).toMatch(/ni adresse ni nom/);
  });

  it('the script no longer contains the clear-text export sub-command', () => {
    const script = fs.readFileSync(path.join(ROOT, 'scripts/gdpr-suite.mjs'), 'utf-8');
    expect(script).not.toMatch(/exports['"`]\)/);
    expect(script).not.toMatch(/new Date\(\)/);
    expect(script).not.toMatch(/src\/db\/index/);
  });
});
